provider-mapper.content:
// Проекция LessonRecord + ClassRecord (lean) → PublicLessonDto
// (`/public/lessons`, ADR-0170). Явный allowlist полей, не «объект целиком
// минус секреты»: маршрут открыт всему интернету, а новое поле в схеме класса
// или занятия иначе утекло бы само (CLAUDE.md, «API»). Zoom-ссылок и паролей
// здесь нет ни у класса, ни у занятия — входной тип их даже не объявляет, а
// spec проверяет точный набор ключей.
//
// Битая строка — не исключение, а причина: контракт Workshop (public-lessons.md,
// случай 6) велит выбросить такое занятие из ответа и записать error-лог, а
// остальные отдать. lean() не подставляет default и не проверяет enum, поэтому
// значения из базы здесь — `unknown`, пока не проверены.
import { Types } from 'mongoose';
import {
  CLASS_FORMATS,
  LESSON_STATUSES,
  type ClassFormat,
  type LessonStatus,
  type PublicLessonDto,
} from '@xuanxue/shared';
import { toIsoUtc } from '../common/iso-date';
import type { LeanLesson } from './lesson.mapper';
import type { LessonClassLookupInput } from './lesson-classes.lookup';

type PublicLessonInput = Pick<
  LeanLesson,
  '_id' | 'startsAt' | 'durationMin' | 'topic' | 'status' | 'tags'
> & { classId: Types.ObjectId };

type PublicClassInput = Pick<
  LessonClassLookupInput,
  'title' | 'groupLabel' | 'format' | 'location'
>;

export type PublicLessonProjection = { dto: PublicLessonDto } | { reason: string };

/** Строка ObjectId или `undefined`, если в поле не ObjectId (битый документ). */
export function objectIdString(value: unknown): string | undefined {
  return value instanceof Types.ObjectId ? value.toString() : undefined;
}

function isOneOf<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === 'string' && (values as readonly string[]).includes(value);
}

function invalidReason(
  lesson: PublicLessonInput,
  cls: PublicClassInput,
): string | undefined {
  const startsAt: unknown = lesson.startsAt;
  if (!(startsAt instanceof Date) || Number.isNaN(startsAt.getTime())) {
    return 'startsAt не дата';
  }
  const duration: unknown = lesson.durationMin;
  if (typeof duration !== 'number' || !Number.isFinite(duration)) {
    return 'durationMin не конечное число';
  }
  const strings: [string, unknown][] = [
    ['topic', lesson.topic],
    ['classTitle', cls.title],
    ['groupLabel', cls.groupLabel],
  ];
  for (const [field, value] of strings) {
    if (typeof value !== 'string') return `${field} не строка`;
  }
  if (!isOneOf<ClassFormat>(CLASS_FORMATS, cls.format)) {
    return 'format вне online/offline/both';
  }
  if (!isOneOf<LessonStatus>(LESSON_STATUSES, lesson.status)) {
    return 'status вне scheduled/cancelled';
  }
  // У дат до ADR-0075 поля `tags` в документе нет — это законно, контракт
  // требует `[]`. Битым считается только присутствующее не-массив-строк.
  const tags: unknown = lesson.tags;
  if (
    tags !== undefined &&
    (!Array.isArray(tags) || tags.some((tag) => typeof tag !== 'string'))
  ) {
    return 'tags не массив строк';
  }
  const location: unknown = cls.location;
  if (location !== undefined && typeof location !== 'string') {
    return 'location не строка';
  }
  return undefined;
}

export function projectPublicLesson(
  lesson: PublicLessonInput,
  cls: PublicClassInput | undefined,
): PublicLessonProjection {
  if (objectIdString(lesson._id) === undefined) return { reason: '_id не ObjectId' };
  if (objectIdString(lesson.classId) === undefined) {
    return { reason: 'classId не ObjectId' };
  }
  if (!cls) return { reason: 'класс не найден' };
  const reason = invalidReason(lesson, cls);
  if (reason !== undefined) return { reason };
  const dto: PublicLessonDto = {
    id: lesson._id.toString(),
    classId: lesson.classId.toString(),
    startsAt: toIsoUtc(lesson.startsAt),
    durationMin: lesson.durationMin,
    classTitle: cls.title,
    groupLabel: cls.groupLabel,
    format: cls.format,
    topic: lesson.topic,
    status: lesson.status,
    tags: lesson.tags ?? [],
  };
  // Ключ `location` — только если адрес есть (контракт: «omitted when absent»).
  // Пустая строка — не «нет адреса»: контракт велит отдавать пустые строки как
  // есть, поэтому проверка на undefined, а не на truthy.
  if (cls.location !== undefined) dto.location = cls.location;
  return { dto };
}

provider-service.content:
// GET /public/lessons (ADR-0170, контракт Workshop) — расписание школы без
// Zoom для daychi. Отдельный сервис, а не флаг у MyLessonsService: две
// проекции в одном методе — риск, что поле для сессии утечёт в публичный
// ответ. Общее — только запрос классов (lesson-classes.lookup.ts).
// Отменённые занятия включены: клиент должен показать «занятия не будет».
import { Injectable, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import type { DateTime } from 'luxon';
import { Model, Types, type QueryFilter } from 'mongoose';
import type { ListPublicLessonsQuery, PublicLessonDto } from '@xuanxue/shared';
import { ClassRecord } from '../classes/class.schema';
import { LessonRecord } from './lesson.schema';
import type { LeanLesson } from './lesson.mapper';
import { findLessonClassesByIds } from './lesson-classes.lookup';
import { objectIdString, projectPublicLesson } from './public-lesson.mapper';
import { resolvePublicLessonsWindow } from './public-lessons-window';

@Injectable()
export class PublicLessonsService {
  private readonly logger = new Logger(PublicLessonsService.name);

  constructor(
    @InjectModel(LessonRecord.name) private readonly model: Model<LessonRecord>,
    @InjectModel(ClassRecord.name) private readonly classModel: Model<ClassRecord>,
  ) {}

  /**
   * Битое занятие (нет класса, поле не того типа) выпадает из ответа с
   * error-логом, остальные уходят с 200 — контракт Workshop, случай 6. Лог
   * обязателен именно здесь: ответ успешный, глобальный фильтр 500 его не
   * увидит. Сбой чтения базы или ошибка кода летят дальше и дают 500.
   */
  async list(
    query: ListPublicLessonsQuery,
    now: DateTime,
    requestId?: string,
  ): Promise<PublicLessonDto[]> {
    const selection = resolvePublicLessonsWindow(query);
    const filter: QueryFilter<LessonRecord> =
      selection.mode === 'count'
        ? { startsAt: { $gte: now.toJSDate() } }
        : { startsAt: { $gte: selection.from.toJSDate(), $lt: selection.to.toJSDate() } };

    const cursor = this.model.find(filter).sort({ startsAt: 1 });
    // Окно — без предела по числу занятий (контракт): ширину ограничивает
    // сама проверка окна, 28 суток. «Ближайшие» берут limit кандидатов до
    // проверки и выпавшее не добирают (контракт: no refill).
    const docs = await (
      selection.mode === 'count' ? cursor.limit(selection.limit) : cursor
    ).lean<LeanLesson[]>();

    const classIds = docs
      .map((doc): unknown => doc.classId)
      .filter((id): id is Types.ObjectId => id instanceof Types.ObjectId);
    const classById = await findLessonClassesByIds(this.classModel, classIds);

    const dtos: PublicLessonDto[] = [];
    for (const doc of docs) {
      const classId = objectIdString(doc.classId);
      const cls = classId === undefined ? undefined : classById.get(classId);
      const projection = projectPublicLesson(doc, cls);
      if ('dto' in projection) {
        dtos.push(projection.dto);
        continue;
      }
      // Тема и Zoom в лог не идут: только id и причина.
      this.logger.error(
        `Публичное занятие пропущено (requestId=${requestId ?? '-'}, lessonId=${objectIdString(doc._id) ?? '-'}, classId=${classId ?? '-'}): ${projection.reason}`,
      );
    }
    return dtos;
  }
}

provider-omission-tests.content:
// e2e на битые занятия GET /public/lessons (ADR-0170, контракт Workshop
// public-lessons.md, случай 6): битое занятие или класс выпадает из ответа
// 200 с error-логом на каждое пропущенное занятие, остальные отдаются; сбой
// чтения — 500 `internal_error`, не 200. Битое значение кладём updateOne мимо
// схемы: create() с required/enum его не пустил бы, а уже лежащий документ
// lean() отдаёт как есть. Часы заморожены через Settings.now Luxon.
import { Logger } from '@nestjs/common';
import { Types } from 'mongoose';
import { Settings } from 'luxon';
import type { ApiErrorBody, PublicLessonDto } from '@xuanxue/shared';
import { createTestApp, type TestApp } from './e2e-support/create-app';
import {
  contractLessonId,
  createPublicLessonHelpers,
  ZOOM_LINK,
  ZOOM_PASSWORD,
} from './e2e-support/public-lessons-fixtures';

const NOW = new Date('2026-10-05T10:00:00.000Z');
const HOUR_MS = 3_600_000;
const REQUEST_ID = 'e2e-omission-1';
const OMISSION_MARK = 'Публичное занятие пропущено';
const WINDOW_QUERY = 'from=2026-10-05T00:00:00%2B03:00&to=2026-10-19T00:00:00%2B03:00';

describe('GET /public/lessons — битые занятия (e2e)', () => {
  let testApp: TestApp;
  const h = createPublicLessonHelpers(() => testApp);
  const realNow = Settings.now;
  let errorLog: jest.SpyInstance;

  beforeAll(async () => {
    Settings.now = () => NOW.getTime();
    testApp = await createTestApp();
  }, 60_000);

  afterAll(async () => {
    Settings.now = realNow;
    await testApp.close();
  });

  beforeEach(() => {
    errorLog = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
  });

  afterEach(async () => {
    errorLog.mockRestore();
    await h.clearAll();
  });

  function omissionLogs(): string[] {
    return errorLog.mock.calls
      .map(([message]) => String(message))
      .filter((message) => message.includes(OMISSION_MARK));
  }

  function at(hours: number): Date {
    return new Date(NOW.getTime() + hours * HOUR_MS);
  }

  async function getIds(query = ''): Promise<string[]> {
    const res = await h.getPublic(query).set('x-request-id', REQUEST_ID);
    expect(res.status).toBe(200);
    return (res.body as PublicLessonDto[]).map((l) => l.id);
  }

  it('смесь: без durationMin, класс с чужим format, без класса — 200 только с целыми', async () => {
    const goodClass = await h.createClass();
    const badClass = await h.createClass();
    await h.classModel().updateOne({ _id: badClass }, { $set: { format: 'hybrid' } });
    const valid = await h.createLesson({ classId: goodClass, startsAt: at(1) });
    const noDuration = await h.createLesson({ classId: goodClass, startsAt: at(2) });
    await h.lessonModel().updateOne({ _id: noDuration }, { $unset: { durationMin: 1 } });
    const badFormat = await h.createLesson({ classId: badClass, startsAt: at(3) });
    const missingClassId = new Types.ObjectId();
    const orphan = await h.createLesson({ classId: missingClassId, startsAt: at(4) });

    expect(await getIds()).toEqual([valid]);

    const logs = omissionLogs();
    expect(logs).toHaveLength(3);
    const expected: [string, string, string][] = [
      [noDuration, goodClass.toString(), 'durationMin'],
      [badFormat, badClass.toString(), 'format'],
      [orphan, missingClassId.toString(), 'класс не найден'],
    ];
    for (const [lessonId, classId, cause] of expected) {
      const line = logs.find((log) => log.includes(`lessonId=${lessonId}`));
      expect(line).toContain(`classId=${classId}`);
      expect(line).toContain(`requestId=${REQUEST_ID}`);
      expect(line).toContain(cause);
    }
    const all = logs.join('\n');
    expect(all).not.toMatch(/zoom/i);
    expect(all).not.toContain(ZOOM_LINK);
    expect(all).not.toContain(ZOOM_PASSWORD);
  });

  it('битый общий класс — выпадают все его занятия, чужие остаются', async () => {
    const goodClass = await h.createClass();
    const badClass = await h.createClass();
    await h.classModel().updateOne({ _id: badClass }, { $set: { format: 'hybrid' } });
    await h.createLesson({ classId: badClass, startsAt: at(1) });
    const valid = await h.createLesson({ classId: goodClass, startsAt: at(2) });
    await h.createLesson({ classId: badClass, startsAt: at(3) });

    expect(await getIds()).toEqual([valid]);
    expect(omissionLogs()).toHaveLength(2);
  });

  it('фикстура контракта: у 003 нет durationMin — 002, 004, 005; починили — снова все четыре', async () => {
    await h.seedContractLessons();
    await h
      .lessonModel()
      .updateOne({ _id: contractLessonId(3) }, { $unset: { durationMin: 1 } });

    expect(await getIds(WINDOW_QUERY)).toEqual([2, 4, 5].map(contractLessonId));
    expect(omissionLogs()).toHaveLength(1);

    await h.lessonModel().updateOne({ _id: contractLessonId(3) }, { durationMin: 60 });

    expect(await getIds(WINDOW_QUERY)).toEqual([2, 3, 4, 5].map(contractLessonId));
  });

  it('все кандидаты битые — 200 и [] с логами', async () => {
    const classId = await h.createClass();
    await h.classModel().updateOne({ _id: classId }, { $set: { format: 'hybrid' } });
    await h.createLesson({ classId, startsAt: at(1) });
    await h.createLesson({ classId, startsAt: at(2) });

    expect(await getIds()).toEqual([]);
    expect(omissionLogs()).toHaveLength(2);
  });

  it('кандидатов нет — 200 и [] без логов пропуска', async () => {
    expect(await getIds()).toEqual([]);
    expect(omissionLogs()).toHaveLength(0);
  });

  it('limit=2, первый кандидат битый — только второй, без добора третьим', async () => {
    const classId = await h.createClass();
    const broken = await h.createLesson({ classId, startsAt: at(1) });
    await h.lessonModel().updateOne({ _id: broken }, { $unset: { durationMin: 1 } });
    const second = await h.createLesson({ classId, startsAt: at(2) });
    await h.createLesson({ classId, startsAt: at(3) });

    expect(await getIds('limit=2')).toEqual([second]);
    expect(omissionLogs()).toHaveLength(1);
  });

  it('пустые строки, нет адреса и тегов — занятие целое, не выпадает', async () => {
    const classId = await h.createClass();
    await h.classModel().updateOne({ _id: classId }, { $set: { title: '' } });
    const id = await h.createLesson({ classId, startsAt: at(1), topic: '' });

    expect(await getIds()).toEqual([id]);
    expect(omissionLogs()).toHaveLength(0);
  });

  it('сбой чтения классов — 500 internal_error, а не 200', async () => {
    const classId = await h.createClass();
    await h.createLesson({ classId, startsAt: at(1) });
    const find = jest.spyOn(h.classModel(), 'find').mockImplementation(() => {
      throw new Error('Mongo недоступна');
    });

    const res = await h.getPublic();
    find.mockRestore();

    expect(res.status).toBe(500);
    expect(Array.isArray(res.body)).toBe(false);
    expect((res.body as ApiErrorBody).code).toBe('internal_error');
    expect(res.text).not.toContain('Mongo недоступна');
    expect(omissionLogs()).toHaveLength(0);
  });
});

provider-public-tests.content:
// e2e на GET /public/lessons (ADR-0170, контракт Workshop public-lessons.md):
// публичное расписание школы без Zoom, два режима выборки. Настоящий AppModule
// на MongoMemoryServer. Часы заморожены через Settings.now Luxon (CLAUDE.md
// «Детерминизм»): контроллер берёт `DateTime.utc()`. Отказы запроса — в
// public-lessons-validation, битые занятия и 500 — в public-lessons-omission.
import { Settings } from 'luxon';
import type { MyLessonDto, PublicLessonDto } from '@xuanxue/shared';
import { createTestApp, type TestApp } from './e2e-support/create-app';
import { sessionCookieFor } from './e2e-support/http';
import {
  contractLessonId,
  createPublicLessonHelpers,
  PUBLIC_LESSONS_PATH,
  ZOOM_LINK,
} from './e2e-support/public-lessons-fixtures';
import request from 'supertest';

const NOW = new Date('2026-10-05T10:00:00.000Z');
const HOUR_MS = 3_600_000;
const CONTRACT_KEYS = [
  'classId',
  'classTitle',
  'durationMin',
  'format',
  'groupLabel',
  'id',
  'location',
  'startsAt',
  'status',
  'tags',
  'topic',
].sort();
const WINDOW_QUERY = 'from=2026-10-05T00:00:00%2B03:00&to=2026-10-19T00:00:00%2B03:00';

describe('GET /public/lessons (e2e)', () => {
  let testApp: TestApp;
  const h = createPublicLessonHelpers(() => testApp);
  const realNow = Settings.now;

  beforeAll(async () => {
    Settings.now = () => NOW.getTime();
    testApp = await createTestApp();
  }, 60_000);

  afterAll(async () => {
    Settings.now = realNow;
    await testApp.close();
  });

  afterEach(h.clearAll);

  async function listIds(query: string): Promise<string[]> {
    const res = await h.getPublic(query);
    expect(res.status).toBe(200);
    return (res.body as PublicLessonDto[]).map((l) => l.id);
  }

  describe('форма ответа', () => {
    it('без сессии — 200, голый массив, поля ровно по контракту', async () => {
      const classId = await h.createClass({ location: 'Тель-Авив' });
      await h.createLesson({
        classId,
        startsAt: new Date(NOW.getTime() + HOUR_MS),
        tags: ['дракон'],
      });

      const res = await h.getPublic();

      expect(res.status).toBe(200);
      const body = res.body as PublicLessonDto[];
      expect(Array.isArray(body)).toBe(true);
      expect(body).toHaveLength(1);
      const [item] = body;
      expect(Object.keys(item ?? {}).sort()).toEqual(CONTRACT_KEYS);
      expect(item).toMatchObject({
        classId: classId.toString(),
        startsAt: '2026-10-05T11:00:00.000Z',
        durationMin: 60,
        classTitle: 'Tai chi',
        groupLabel: 'School',
        format: 'both',
        location: 'Тель-Авив',
        topic: 'Practice',
        status: 'scheduled',
        tags: ['дракон'],
      });
    });

    it('занятие без тегов — tags: [], класс без адреса — ключа location нет', async () => {
      const classId = await h.createClass();
      await h.createLesson({ classId, startsAt: new Date(NOW.getTime() + HOUR_MS) });

      const [item] = (await h.getPublic()).body as PublicLessonDto[];

      expect(item?.tags).toEqual([]);
      expect(item).not.toHaveProperty('location');
      expect(Object.keys(item ?? {})).toHaveLength(CONTRACT_KEYS.length - 1);
    });

    it('два занятия одного класса — один classId, разные id', async () => {
      const classId = await h.createClass();
      await h.createLesson({ classId, startsAt: new Date(NOW.getTime() + HOUR_MS) });
      await h.createLesson({ classId, startsAt: new Date(NOW.getTime() + 2 * HOUR_MS) });

      const body = (await h.getPublic()).body as PublicLessonDto[];

      expect(body).toHaveLength(2);
      expect(body[0]?.classId).toBe(body[1]?.classId);
      expect(body[0]?.id).not.toBe(body[1]?.id);
    });
  });

  describe('проекция без Zoom', () => {
    async function expectNoZoom(cookie?: string): Promise<void> {
      const classId = await h.createClass({ location: 'Зал' });
      await h.createLesson({
        classId,
        startsAt: new Date(NOW.getTime() + HOUR_MS),
        withZoomOverride: true,
      });

      const res = await h.getPublic('', cookie);

      expect(res.status).toBe(200);
      const [item] = res.body as PublicLessonDto[];
      expect(Object.keys(item ?? {}).sort()).toEqual(CONTRACT_KEYS);
      expect(item).not.toHaveProperty('zoomLink');
      expect(item).not.toHaveProperty('zoomPassword');
      expect(item).not.toHaveProperty('zoomLinkOverride');
      // Текст целиком: ни ключа, ни значения секрета, ни под другим именем.
      expect(res.text).not.toMatch(/zoom/i);
      expect(res.text).not.toContain('секрет');
    }

    it('без сессии у класса и занятия с Zoom — ни ссылки, ни пароля', async () => {
      await expectNoZoom();
    });

    it('с сессией admin ответ тот же — сессия проекцию не расширяет', async () => {
      await expectNoZoom(await sessionCookieFor(testApp.app, ['admin']));
    });
  });

  describe('режим «ближайшие»', () => {
    it('по умолчанию — 10 из 12 будущих, по возрастанию startsAt', async () => {
      const classId = await h.createClass();
      await h.createLessonsEveryMinute(classId, new Date(NOW.getTime() + HOUR_MS), 12);

      const body = (await h.getPublic()).body as PublicLessonDto[];

      expect(body).toHaveLength(10);
      expect(body.map((l) => l.topic)).toEqual(
        Array.from({ length: 10 }, (_, i) => `Занятие ${i}`),
      );
    });

    it('limit=1 — одно ближайшее', async () => {
      const classId = await h.createClass();
      await h.createLessonsEveryMinute(classId, new Date(NOW.getTime() + HOUR_MS), 3);

      const body = (await h.getPublic('limit=1')).body as PublicLessonDto[];

      expect(body.map((l) => l.topic)).toEqual(['Занятие 0']);
    });

    it('limit=50 при 60 занятиях — ровно 50', async () => {
      const classId = await h.createClass();
      await h.createLessonsEveryMinute(classId, new Date(NOW.getTime() + HOUR_MS), 60);

      expect(await listIds('limit=50')).toHaveLength(50);
    });

    it('занятие ровно в now включено, на секунду раньше — нет', async () => {
      const classId = await h.createClass();
      const atNow = await h.createLesson({ classId, startsAt: NOW });
      await h.createLesson({ classId, startsAt: new Date(NOW.getTime() - 1000) });

      expect(await listIds('limit=50')).toEqual([atNow]);
    });

    it('отменённое будущее занятие остаётся в списке со статусом cancelled', async () => {
      const classId = await h.createClass();
      await h.createLesson({
        classId,
        startsAt: new Date(NOW.getTime() + HOUR_MS),
        status: 'cancelled',
      });

      const body = (await h.getPublic()).body as PublicLessonDto[];

      expect(body.map((l) => l.status)).toEqual(['cancelled']);
    });
  });

  describe('режим «окно»', () => {
    const SEEDED = [2, 3, 4, 5].map(contractLessonId);

    it('фикстура контракта 001–006 — ровно 002, 003, 004, 005; 004 отменено', async () => {
      await h.seedContractLessons();

      const res = await h.getPublic(WINDOW_QUERY);

      expect(res.status).toBe(200);
      const body = res.body as PublicLessonDto[];
      expect(body.map((l) => l.id)).toEqual(SEEDED);
      expect(body.map((l) => l.status)).toEqual([
        'scheduled',
        'scheduled',
        'cancelled',
        'scheduled',
      ]);
    });

    it('смещение в виде +0300 даёт те же границы, now окно не сужает', async () => {
      await h.seedContractLessons();

      const ids = await listIds(
        'from=2026-10-05T00:00:00%2B0300&to=2026-10-19T00:00:00%2B0300',
      );

      expect(ids).toEqual(SEEDED);
    });

    it('перенос 003 внутри окна — тот же id, теперь после 004', async () => {
      await h.seedContractLessons();
      await h.moveLesson(3, '2026-10-07T15:00:00Z');

      const body = (await h.getPublic(WINDOW_QUERY)).body as PublicLessonDto[];

      expect(body.map((l) => l.id)).toEqual([2, 4, 3, 5].map(contractLessonId));
      expect(body.find((l) => l.id === contractLessonId(3))?.startsAt).toBe(
        '2026-10-07T15:00:00.000Z',
      );
    });

    it('перенос 003 за окно — его в ответе нет', async () => {
      await h.seedContractLessons();
      await h.moveLesson(3, '2026-10-20T15:00:00Z');

      expect(await listIds(WINDOW_QUERY)).toEqual([2, 4, 5].map(contractLessonId));
    });

    it('отмена 005 — остаётся в ответе с тем же id и статусом cancelled', async () => {
      await h.seedContractLessons();
      await h
        .lessonModel()
        .updateOne({ _id: contractLessonId(5) }, { status: 'cancelled' });

      const body = (await h.getPublic(WINDOW_QUERY)).body as PublicLessonDto[];

      const moved = body.find((l) => l.id === contractLessonId(5));
      expect(moved?.status).toBe('cancelled');
      expect(body).toHaveLength(4);
    });

    it('пустое окно — 200 и []', async () => {
      expect(await listIds(WINDOW_QUERY)).toEqual([]);
    });

    it('201 занятие в окне — все 201, без limit и пагинации', async () => {
      const classId = await h.createClass();
      await h.createLessonsEveryMinute(classId, new Date('2026-10-05T00:00:00Z'), 201);

      const ids = await listIds('from=2026-10-05T00:00:00Z&to=2026-10-06T00:00:00Z');

      expect(ids).toHaveLength(201);
      expect(new Set(ids).size).toBe(201);
    });

    it('пример со сменой смещения (337 часов) принимается', async () => {
      const query = 'from=2024-10-20T00:00:00%2B03:00&to=2024-11-03T00:00:00%2B02:00';

      expect(await listIds(query)).toEqual([]);
    });
  });

  describe('прочее', () => {
    // У контроллера один маршрут. Утверждение 404 на путь под
    // /api/public/lessons — ещё и то, что check-ownership-e2e.mjs требует от
    // спека контроллера: «чужое» здесь не бывает, расписание школы общее и
    // публичное, поэтому отказ проверяем на лишнем пути, а не на владельце.
    it('GET /api/public/lessons/anything — 404', async () => {
      const res = await request(h.server()).get(`${PUBLIC_LESSONS_PATH}/anything`);
      expect(res.status).toBe(404);
    });

    // Регресс: защищённый маршрут ученика не тронут, Zoom в нём по-прежнему есть.
    it('GET /api/me/lessons с сессией по-прежнему отдаёт zoomLink', async () => {
      const classId = await h.createClass();
      await h.createLesson({ classId, startsAt: new Date(NOW.getTime() + HOUR_MS) });
      const cookie = await sessionCookieFor(testApp.app, []);

      const res = await request(h.server()).get('/api/me/lessons').set('Cookie', cookie);

      expect(res.status).toBe(200);
      expect((res.body as MyLessonDto[])[0]?.zoomLink).toBe(ZOOM_LINK);
    });
  });
});

provider-join.content:
// Общий join «занятия ученика → классы по id», вынесенный из
// MyLessonsService.findClassesByIds (CLAUDE.md «Одна механика — один
// компонент»): и `/me/lessons`, и `/me/lessons/archive` подтягивают классы
// тем же приёмом ($in + Map) и одинаково собирают из них DTO (расшифровка
// занятия + пропуск даты без класса) — второй раз этот код не пишется,
// оба сервиса зовут функции отсюда (иначе jscpd считает дубль).
import type { Model, Types } from 'mongoose';
import { CLASS_ENCRYPT_SCHEMA, ClassRecord } from '../classes/class.schema';
import { decryptRecord } from '../utils/encryption';
import { LESSON_ENCRYPT_SCHEMA } from './lesson.schema';
import type { LeanLesson } from './lesson.mapper';

/** `Pick<ClassRecord, ...>` вместо простого пересечения — тот же приём, что
 * у RawLeanExam/RawLeanExamItem (exam.mapper.ts/exam-item.mapper.ts): иначе
 * тип не проходит ограничение `T extends Record<string, unknown>` у
 * decryptRecord. */
export type LessonClassLookupInput = Pick<
  ClassRecord,
  'title' | 'groupLabel' | 'format' | 'location' | 'zoomLink' | 'zoomPassword'
> & { _id: Types.ObjectId };

export async function findLessonClassesByIds(
  classModel: Model<ClassRecord>,
  classIds: Types.ObjectId[],
): Promise<Map<string, LessonClassLookupInput>> {
  const uniqueIds = [...new Set(classIds.map((id) => id.toString()))];
  const docs = await classModel
    .find({ _id: { $in: uniqueIds } })
    .lean<LessonClassLookupInput[]>();
  return new Map(
    docs.map((doc) => [doc._id.toString(), decryptRecord(doc, CLASS_ENCRYPT_SCHEMA)]),
  );
}

/**
 * Расшифровывает каждую дату занятия и собирает из неё DTO вместе с классом
 * из `classById` (см. `findLessonClassesByIds`). Дата, у которой класс не
 * нашёлся — рассинхрон данных (класс у даты занятия удалить нельзя, пока на
 * него ссылается хоть одна дата, ClassesService.remove); её молча
 * пропускают, не роняя весь список ученику.
 */
export function joinLessonsWithClasses<T>(
  docs: LeanLesson[],
  classById: Map<string, LessonClassLookupInput>,
  toDto: (lesson: LeanLesson, cls: LessonClassLookupInput) => T,
): T[] {
  return docs
    .map((doc) => {
      const cls = classById.get(doc.classId.toString());
      if (!cls) return null;
      return toDto(decryptRecord(doc, LESSON_ENCRYPT_SCHEMA), cls);
    })
    .filter((dto): dto is T => dto !== null);
}

provider-dto.content:
// Публичное расписание школы для daychi (`GET /api/public/lessons`, ADR-0170).
// Контракт Workshop, ревизия 4aec5f84130c2dd8df6875c30fd94c3cf2a5ec74:
// https://github.com/dveyarangi/xuanxue-workshop/blob/4aec5f84130c2dd8df6875c30fd94c3cf2a5ec74/docs/contracts/public-lessons.md
// Ровно проекция контракта, без Zoom и служебных полей: маршрут открыт всему
// интернету, поэтому лишнее поле здесь — утечка (маппер в api — allowlist).
import type { ClassFormat, LessonStatus } from './domain';

export interface PublicLessonDto {
  id: string;
  classId: string;
  startsAt: string; // ISO UTC с Z
  durationMin: number;
  classTitle: string;
  groupLabel: string;
  format: ClassFormat;
  /** Нет адреса у класса — ключа в ответе нет (контракт: единственное необязательное поле). */
  location?: string;
  topic: string;
  status: LessonStatus;
  tags: string[];
}

/** Два режима, смешивать нельзя: `limit` (ближайшие) либо оба `from`+`to`
 * (полное окно) — правило проверяет `resolvePublicLessonsWindow` в api. */
export interface ListPublicLessonsQuery {
  limit?: number;
  from?: string;
  to?: string;
}

// Пределы взяты из контракта Workshop (ссылка в шапке файла), а не придуманы
// здесь: daychi рассчитывает на них, менять в одностороннем порядке нельзя.
export const PUBLIC_LESSONS_LIMIT_DEFAULT = 10;
export const PUBLIC_LESSONS_LIMIT_MAX = 50;
/** Окно не шире 4 недель = 28 суток UTC; ровно 28 суток допустимо. */
export const PUBLIC_LESSONS_WINDOW_MAX_WEEKS = 4;

